package com.saasresearcher.learning.reporting.entity;

import com.saasresearcher.learning.reporting.api.ExportStatus;
import com.saasresearcher.learning.reporting.api.ReportType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.UUID;
import lombok.Getter;

/** A CSV export generated by a job into private storage, downloadable only by the requesting course author. */
@Getter
@Entity
@Table(name = "report_exports")
public class ReportExport {

    @Id
    private UUID id;

    @Column(name = "course_id", nullable = false, updatable = false)
    private UUID courseId;

    @Column(name = "course_version_id", updatable = false)
    private UUID courseVersionId;

    @Column(name = "requested_by", nullable = false, updatable = false)
    private UUID requestedBy;

    @Column(nullable = false, updatable = false)
    private ReportType type;

    @Column(nullable = false)
    private ExportStatus status;

    @Column(name = "storage_key", nullable = false, updatable = false)
    private String storageKey;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "completed_at")
    private Instant completedAt;

    protected ReportExport() {
    }

    public ReportExport(UUID courseId, UUID courseVersionId, UUID requestedBy, ReportType type, Instant now) {
        this.id = UUID.randomUUID();
        this.courseId = courseId;
        this.courseVersionId = courseVersionId;
        this.requestedBy = requestedBy;
        this.type = type;
        this.status = ExportStatus.PENDING;
        this.storageKey = "reports/" + id;
        this.createdAt = now;
    }

    public void complete(ExportStatus status, Instant now) {
        this.status = status;
        this.completedAt = now;
    }
}
